      var lo = i === 0 ? 0 : (BROSELOW_TAPE[i - 1].wMax + z.wMin) / 2;
      var hi = i === BROSELOW_TAPE.length - 1 ? Infinity : (z.wMax + BROSELOW_TAPE[i + 1].wMin) / 2;
      if (w >= lo && w < hi) return z;
